import SwiftUI
import UIKit
import ImageIO

/// The attn character used in the Home badge and Standby display.
/// Home uses the same transparent animation as Standby, scaled into the
/// existing gradient badge. Reduced Motion uses the supplied still artwork.
public struct AttnMascot: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    private let width: CGFloat
    private let accessibilityText: String

    public init(width: CGFloat = 180, accessibilityLabel: String = "attn mascot") {
        self.width = width
        self.accessibilityText = accessibilityLabel
    }

    public var body: some View {
        Group {
            if !reduceMotion, !AttnMascotImage.animationFrames.isEmpty {
                TimelineView(.animation(minimumInterval: 1.0 / 15.0)) { context in
                    let frames = AttnMascotImage.animationFrames
                    let frameIndex = Int(context.date.timeIntervalSinceReferenceDate * 15)
                        % frames.count

                    Image(uiImage: frames[frameIndex])
                        .resizable()
                        .interpolation(.high)
                        .scaledToFit()
                }
            } else if let image = AttnMascotImage.still {
                Image(uiImage: image)
                    .resizable()
                    .interpolation(.high)
                    .scaledToFit()
            } else {
                Image(systemName: "person.fill")
                    .font(.system(size: width * 0.28, weight: .medium))
                    .foregroundStyle(.white)
            }
        }
        .frame(width: width, height: width * CGFloat(2048) / CGFloat(1435))
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(accessibilityText)
        .accessibilityAddTraits(.isImage)
    }
}

/// Standby treatment: the animated new mascot with Figma's question bubble.
public struct AttnMascotQuestion: View {
    private let width: CGFloat
    private let accessibilityText: String

    public init(width: CGFloat = 360, accessibilityLabel: String = "attn mascot, standby state") {
        self.width = width
        self.accessibilityText = accessibilityLabel
    }

    public var body: some View {
        ZStack(alignment: .topTrailing) {
            AttnMascot(width: width, accessibilityLabel: accessibilityText)
                .accessibilityHidden(true)

            PixelQuestionBubble()
                .fill(Color(red: 0.90, green: 0.89, blue: 0.87))
                .overlay {
                    Text("?")
                        .font(.system(size: width * 0.22, weight: .black, design: .rounded))
                        .foregroundStyle(Color(red: 25 / 255, green: 25 / 255, blue: 25 / 255))
                        .offset(y: -width * 0.01)
                }
                .frame(width: width * 0.422, height: width * 0.356)
                .offset(x: -width * 0.054, y: width * 0.236)
                .accessibilityHidden(true)
        }
        .frame(width: width, height: width * CGFloat(2048) / CGFloat(1435))
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(accessibilityText)
        .accessibilityAddTraits(.isImage)
    }
}

/// The compact circular Home-nav control.
public struct AttnMascotBadge: View {
    private let size: CGFloat
    private let action: () -> Void

    public init(size: CGFloat = 50, action: @escaping () -> Void = {}) {
        self.size = size
        self.action = action
    }

    public var body: some View {
        Button(action: action) {
            ZStack {
                Circle()
                    .fill(
                        LinearGradient(
                            colors: [
                                Color(red: 0, green: 159 / 255, blue: 254 / 255),
                                Color(red: 249 / 255, green: 251 / 255, blue: 227 / 255)
                            ],
                            startPoint: .top,
                            endPoint: .bottom
                        )
                    )

                AttnMascot(width: size * 0.464)
                    .offset(y: size * 0.01)
                    .accessibilityHidden(true)
            }
            .frame(width: size, height: size)
            .clipShape(Circle())
            .contentShape(Circle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel("Open standby display")
        .accessibilityHint("Shows the time, mascot, and priorities that need attention.")
    }
}

private struct PixelQuestionBubble: Shape {
    func path(in rect: CGRect) -> Path {
        let w = rect.width
        let h = rect.height
        var path = Path()
        path.move(to: CGPoint(x: w * 0.10, y: 0))
        path.addLine(to: CGPoint(x: w * 0.90, y: 0))
        path.addLine(to: CGPoint(x: w * 0.90, y: h * 0.10))
        path.addLine(to: CGPoint(x: w, y: h * 0.10))
        path.addLine(to: CGPoint(x: w, y: h * 0.80))
        path.addLine(to: CGPoint(x: w * 0.65, y: h * 0.80))
        path.addLine(to: CGPoint(x: w * 0.56, y: h))
        path.addLine(to: CGPoint(x: w * 0.47, y: h * 0.80))
        path.addLine(to: CGPoint(x: w * 0.10, y: h * 0.80))
        path.addLine(to: CGPoint(x: w * 0.10, y: h * 0.70))
        path.addLine(to: CGPoint(x: 0, y: h * 0.70))
        path.addLine(to: CGPoint(x: 0, y: h * 0.10))
        path.addLine(to: CGPoint(x: w * 0.10, y: h * 0.10))
        path.closeSubpath()
        return path
    }
}

private enum AttnMascotImage {
    static let still: UIImage? = {
        guard let data = Data(base64Encoded: AttnMascotStillPNG.base64) else { return nil }
        return UIImage(data: data)
    }()

    static let animationFrames: [UIImage] = {
        guard
            let data = Data(base64Encoded: AttnMascotAnimationGIF.base64),
            let source = CGImageSourceCreateWithData(data as CFData, nil)
        else { return [] }

        let count = CGImageSourceGetCount(source)
        guard count > 1 else { return [] }

        return (0..<count).compactMap { index in
            guard let frame = CGImageSourceCreateImageAtIndex(source, index, nil) else { return nil }
            return UIImage(cgImage: frame, scale: 1, orientation: .up)
        }
    }()

}

private enum AttnMascotStillPNG {
    static let base64 = ""
}

private enum AttnMascotAnimationGIF {
    static let base64 = ""
}
